import std.collection.HashMap
import std.time.DateTime
import std.time.Duration
import std.log.*

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request["path"] as String
        let method = request["method"] as String

        if self.is_start_with(request_uri: request_uri) {
            return true
        }

        do {
            let token = self.get_jwt_user(request: request)
            switch token {
                case is Some<HashMap<String, Any>>:
                    let user = (token as Some<HashMap<String, Any>>).value["user"] as HashMap<String, Any>
                    if (user["level"] as Int64) > 2 {
                        self.set_current_user_info_and_log(user: user)
                        return true
                    } else {
                        return false
                    }
                case is None:
                    return false
            }
        } catch {
            return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        let start_with = ["/api", "/login"]
        for s in start_with {
            if request_uri.startsWith(s) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any>
        let token = headers["Authorization"] as HashMap<String, Any>
        let user = token["user"] as HashMap<String, Any>
        let jwt = token["jwt"] as String
        if jwt.startsWith(user["name"] as String) {
            let jwt_str_date = jwt.substring((user["name"] as String).count)
            let formatter = DateTimeFormatter("yyyy-MM-dd")
            let jwt_date = DateTime.parse(jwt_str_date, formatter)
            let today = DateTime.now()
            if today - jwt_date >= Duration(days: 3) {
                return None()
            }
        }
        return Some(token)
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user["name"] as String
        let host = user["address"] as String
        let now = DateTime.now()
        let formatter = DateTimeFormatter("yyyy-MM-dd HH:mm:ss")
        let log_msg = "${name}${host}${now.format(formatter)}"
        Logger.log(msg: log_msg, level: Level.INFO)
    }
}

