import std.collection.*
import std.reflect.*
import std.convert.*
import std.string.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.trim() |> split(" ")
        if (parts.size < 2) {
            let missing = required.clone()
            return (false, missing.isNull() ? none : some(missing))
        }

        var i = 1  // Skip program name
        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let keyValue = part[2..].split("=", limit: 2)
                if (keyValue.size == 2) {
                    let key = keyValue[0]
                    let valueStr = keyValue[1]
                    arguments.add(key, convert_type(key, valueStr))
                } else {
                    arguments.add(part[2..], true)
                }
                i += 1
            } else if (part.startsWith("-")) {
                let key = part[1..]
                if (i + 1 < parts.size && !parts[i + 1].startsWith("-")) {
                    arguments.add(key, convert_type(key, parts[i + 1]))
                    i += 2
                } else {
                    arguments.add(key, true)
                    i += 1
                }
            } else {
                i += 1
            }
        }

        let missingArgs = required - arguments.keys.toHashSet()
        if (missingArgs.size > 0) {
            return (false, some(missingArgs))
        }
        return (true, none)
    }

    public func get_argument(key: String): Any {
        return arguments.get(key).getOrElse(none)
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            required.add(arg)
        }
        types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        if (!types.contains(arg)) {
            return value
        }

        let typeInfo = types.get(arg).getOrThrow()
        if (typeInfo == TypeInfo.of<String>()) {
            return value
        } else if (typeInfo == TypeInfo.of<Int64>()) {
            return tryConvert<Int64>(value).getOrElse(value)
        } else if (typeInfo == TypeInfo.of<Float64>()) {
            return tryConvert<Float64>(value).getOrElse(value)
        } else if (typeInfo == TypeInfo.of<Bool>()) {
            let lower = value.toLowerCase()
            if (lower == "true" || lower == "1") {
                return true
            } else if (lower == "false" || lower == "0") {
                return false
            }
            return value
        } else {
            return value
        }
    }

    private func tryConvert<T: ConvertibleFromString>(value: String): Option<T> {
        return T.FromString(value)
    }
}
