        */
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..datas.size+1) {
            let partial_result = ArrayList<ArrayList<Int64>>()
            select_permutations(ArrayList<Int64>(), datas, i, partial_result)
            result.addAll(partial_result)
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
