        :param n: Int64, the number to calculate the factorial.
        :return: Int64, the factorial of the given number.
        >>> ArrangementCalculator.factorial(4)
        24

        */
        if (n == 0_i64 || n == 1_i64) {
            return 1_i64
        }
        var result = 1_i64
        for (i in 2..n+1) {
            result *= i
        }
        return result
    }

