import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'

        */
        var filteredChars = ArrayList<String>()
        for (c in this.expr) {
            let charStr = c.toString()
            if (this.left_brackets.contains(charStr) || this.right_brackets.contains(charStr)) {
                filteredChars.add(charStr)
            }
        }
        this.expr = filteredChars.join("")
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true

        */
        this.clear_expr()
        for (c in this.expr) {
            let charStr = c.toString()
            if (this.left_brackets.contains(charStr)) {
                this.stack.add(charStr)
            } else {
                if (this.stack.size() == 0) {
                    return false
                }
                let currentBrkt = this.stack.removeLast()
                if ((currentBrkt == "(" && charStr != ")") ||
                    (currentBrkt == "{" && charStr != "}") ||
                    (currentBrkt == "[" && charStr != "]")) {
                    return false
                }
            }
        }
        return this.stack.size() == 0
    }
}

main(): Unit {
    let testCases = ArrayList<String>([
        "a(b)c",    // true
        "([{}])",  // true
        "{(])",    // false
        "",        // true
        "[",       // false
        "]",       // false
        "((()))",  // true
        "({[]})",  // true
        "({[}])",  // false
        "a[b{c}d]e(f)g",  // true
        "a[b{c}d)e(f]g"   // false
    ])

    for (testCase in testCases) {
        let b = BalancedBrackets(testCase)
        let result = b.check_balanced_brackets()
        println("Testing `${testCase}`: ${result}")
    }
}

