class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        let maxLength = max(num1.length, num2.length)
        let paddedNum1 = num1.zfill(maxLength)
        let paddedNum2 = num2.zfill(maxLength)

        var carry = 0_i64
        var result = VArray<Int64>()
        for i in range(maxLength - 1, -1, -1) {
            let digit1 = paddedNum1[i].toInteger() as! Int64
            let digit2 = paddedNum2[i].toInteger() as! Int64
            let digitSum = digit1 + digit2 + carry
            carry = digitSum / 10
            result.push(digitSum % 10)
        }

        if carry > 0 {
            result.push(carry)
        }

        var strBuilder = StringBuilder()
        for i in range(result.length - 1, -1, -1) {
            strBuilder.append(result[i].toString())
        }
        return strBuilder.toString()
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        var num1Str = num1
        var num2Str = num2
        var negative = false

        if num1Str.length < num2Str.length {
            (num1Str, num2Str) = (num2Str, num1Str)
            negative = true
        } else if num1Str.length == num2Str.length {
            if num1Str < num2Str {
                (num1Str, num2Str) = (num2Str, num1Str)
                negative = true
            }
        }

        let maxLength = num1Str.length
        let paddedNum1 = num1Str.zfill(maxLength)
        let paddedNum2 = num2Str.zfill(maxLength)

        var borrow = 0_i64
        var result = VArray<Int64>()
        for i in range(maxLength - 1, -1, -1) {
            let digit1 = paddedNum1[i].toInteger() as! Int64
            let digit2 = paddedNum2[i].toInteger() as! Int64
            let digitDiff = digit1 - digit2 - borrow

            if digitDiff < 0 {
                result.push(digitDiff + 10)
                borrow = 1
            } else {
                result.push(digitDiff)
                borrow = 0
            }
        }

        // Remove leading zeros
        var start = 0
        while start < result.length - 1 && result[start] == 0 {
            start += 1
        }

        var strBuilder = StringBuilder()
        for i in range(result.length - 1, start - 1, -1) {
            strBuilder.append(result[i].toString())
        }
        var resultStr = strBuilder.toString()

        if negative {
            resultStr = "-" + resultStr
        }

        return resultStr
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        let len1 = num1.length
        let len2 = num2.length
        var result = VArray<Int64>(capacity: len1 + len2)
        for i in range(0, len1 + len2) {
            result.push(0)
        }

        for i in range(len1 - 1, -1, -1) {
            for j in range(len2 - 1, -1, -1) {
                let digit1 = num1[i].toInteger() as! Int64
                let digit2 = num2[j].toInteger() as! Int64
                let mul = digit1 * digit2
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]

                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        // Remove leading zeros
        var start = 0
        while start < result.length - 1 && result[start] == 0 {
            start += 1
        }

        var strBuilder = StringBuilder()
        for i in range(start, result.length) {
            strBuilder.append(result[i].toString())
        }
        return strBuilder.toString()
    }
}

