import std.collection.HashMap
import std.convert.RadixConvertible
import std.string

class BinaryDataProcessor {
    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = String()
        for c in this.binary_string.chars() {
            if c == '0' || c == '1' {
                cleaned += c
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let zeroes_count = this.binary_string.count('0')
        let ones_count = this.binary_string.count('1')
        let total_length = this.binary_string.length()

        let zeroes_percentage = zeroes_count / total_length
        let ones_percentage = ones_count / total_length

        let result = HashMap<String, Float64>()
        result.put("Zeroes", zeroes_percentage)
        result.put("Ones", ones_percentage)
        result.put("Bit length", total_length.toFloat64())
        return result
    }

    public func convert_to_ascii(): String {
        var byteArray = ByteArray()
        for i in 0..<(this.binary_string.length() / 8) {
            let start = i * 8
            let end = start + 8
            let byteStr = this.binary_string.substring(start, end)
            let decimal = byteStr.toInt32(2) ?? 0
            byteArray.append(decimal.toUInt8())
        }
        return String.fromByteArray(byteArray)
    }

    public func convert_to_utf8(): String {
        // For UTF-8 conversion in this context, it's same as ASCII since we're processing bytes
        // In a real scenario, would need more complex handling for multi-byte UTF-8 characters
        return this.convert_to_ascii()
    }
}

