import std.collection.ArrayList

class BoyerMooreSearch {
    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        for (var i = this.patLen - 1; i >= 0; i--) {
            if (this.pattern[i] == char[0]) { // Assume char is single character string
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        for (var i = this.patLen - 1; i >= 0; i--) {
            if (currentPos + i >= this.textLen) {
                return -1
            }
            if (this.pattern[i] != this.text[currentPos + i]) {
                return currentPos + i
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        var i: Int64 = 0
        while (i <= this.textLen - this.patLen) {
            let mismatchIndex = this.mismatch_in_text(i)
            if (mismatchIndex == -1) {
                positions.add(i)
                i += 1
            } else {
                let charInQuestion = String([this.text[mismatchIndex]])
                let matchIndex = this.match_in_pattern(charInQuestion)
                if (matchIndex == -1) {
                    i = mismatchIndex + 1
                } else {
                    i = mismatchIndex - matchIndex + 1
                }
            }
        }
        return positions
    }
}

