import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {
    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (i in 0..<events.size()) {
            if (events[i] == event) {
                events.remove(i)
                return
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in events) {
            if (event.start_time.year() == date.year() && 
                event.start_time.month() == date.month() && 
                event.start_time.dayOfMonth() == date.dayOfMonth()) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in events) {
            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let slots = ArrayList<(DateTime, DateTime)>()
        var current_start = DateTime(year: date.year(), month: date.month(), dayOfMonth: date.dayOfMonth())
        let slot_duration = DateTime.ofMinutes(60)
        let end_of_day = DateTime(year: date.year(), month: date.month(), 
                                 dayOfMonth: date.dayOfMonth(), 
                                 hour: 23, minute: 59)

        while (current_start < end_of_day) {
            let current_end = current_start.add(slot_duration)
            if (current_end > end_of_day) {
                current_end = end_of_day.add(DateTime.ofMinutes(1)) // Include full last minute
            }
            if (is_available(start_time: current_start, end_time: current_end)) {
                slots.add((current_start, current_end))
            }
            current_start = current_end
        }
        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()
        for (event in events) {
            if (event.start_time >= now) {
                upcoming.add(event)
            }
        }
        // Sort events by start time
        let comparator = {l: Event, r: Event => l.start_time.compareTo(r.start_time)}
        sort(upcoming, by: comparator)

        let result = ArrayList<Event>()
        for (i in 0..<(upcoming.size()).min(num_events)) {
            result.add(upcoming[i])
        }
        return result
    }
}

