import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()
        var file = try? File.open(file_name, FileMode.Read) defer { file?.close() }
        if (file == null) {
            return (title, data)
        }
        var reader = BufReader(file!)
        var firstLine = true
        var line: String
        while (true) {
            line = try? reader.readLine() ?: ""
            if (line.isEmpty()) {
                break
            }
            var parts = ArrayList<String>()
            var buffer = ""
            var inQuotes = false
            for (c in line.chars()) {
                if (c == '"') {
                    inQuotes = !inQuotes
                } else if (c == ',' && !inQuotes) {
                    parts.append(buffer)
                    buffer = ""
                } else {
                    buffer += c.toString()
                }
            }
            parts.append(buffer)
            if (firstLine) {
                title = parts
                firstLine = false
            } else {
                data.append(parts)
            }
        }
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if (data.isEmpty() || data[0].isEmpty()) {
            return 0
        }
        var file = try? File.create(file_name) defer { file?.close() }
        if (file == null) {
            return 0
        }
        var writer = BufWriter(file!)
        for (row in data) {
            for ((i, item) in row.iterator().enumerate()) {
                if (i != 0) {
                    try? writer.write("""")
                    try? writer.write(',')
                }
                try? writer.write("\"${item}\"")
            }
            try? writer.write("\n")
        }
        try? writer.flush()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        var (title, data) = this.read_csv(save_file_name)
        if (title.isEmpty() || N >= title.size() || data.isEmpty()) {
            return 0
        }
        var columnData = ArrayList<String>()
        for (row in data) {
            if (N < row.size()) {
                columnData.append(row[N].toUpperCase())
            }
        }
        var newData = ArrayList<ArrayList<String>>()
        newData.append(title)
        newData.append(columnData)
        var newFileName = save_file_name.substring(0, save_file_name.lastIndexOf('.')) + "_process.csv"
        return this.write_csv(newData, newFileName)
    }
}

