import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        */
        prepare(transform(expression))
        let reversedStack = ArrayList<String>()
        for (i in postfix_stack.size - 1 ... 0) {
            reversedStack.add(postfix_stack[i])
        }
        const resultStack = ArrayList<String>()
        for (op in reversedStack) {
            if (!is_operator(op)) {
                let processedOp = if (op.first() == '~') {
                    String("-") + op.substring(1)
                } else {
                    op
                }
                resultStack.add(processedOp)
            } else {
                const secondValue = Decimal.fromString(resultStack.pop())!
                const firstValue = Decimal.fromString(resultStack.pop())!
                const result = _calculate(firstValue, secondValue, op)
                resultStack.add(result.toString())
            }
        }
        var multiplier = "1"
        var finalResult = Decimal.fromString(resultStack.pop())!
        while (resultStack.size > 0) {
            finalResult *= Decimal.fromString(resultStack.pop())!
        }
        return finalResult.toFloat64()
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        */
        let opStack = ArrayList<String>()
        opStack.add(",")
        const expressionArr = expression.toCharArray()
        var currentIndex = 0
        var count = 0
        for (i in 0 ... expressionArr.size - 1) {
            const currentOp = String.fromChar(expressionArr[i])
            if (is_operator(currentOp)) {
                if (count > 0) {
                    var token = ""
                    for (j in currentIndex ... currentIndex + count - 1) {
                        token += String.fromChar(expressionArr[j])
                    }
                    postfix_stack.add(token)
                }
                const peekOp = opStack.last()
                if (currentOp == ")") {
                    while (opStack.last() != "(") {
                        postfix_stack.add(opStack.pop())
                    }
                    opStack.pop()
                } else {
                    while (currentOp != "(" && peekOp != "," && compare(currentOp, peekOp)) {
                        postfix_stack.add(opStack.pop())
                    }
                    opStack.add(currentOp)
                }
                count = 0
                currentIndex = i + 1
            } else {
                count++
            }
        }
        if (count > 1 || (count == 1 && !is_operator(String.fromChar(expressionArr[currentIndex])))) {
            var token = ""
            for (j in currentIndex ... currentIndex + count - 1) {
                token += String.fromChar(expressionArr[j])
            }
            postfix_stack.add(token)
        }
        while (opStack.last() != ",") {
            postfix_stack.add(opStack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        */
        return c.matchesRegex(#"^[+\-*/()%]$"#)
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        */
        var curPriority = cur
        var peekPriority = peek
        if (cur == "%") {
            curPriority = "/"
        }
        if (peek == "%") {
            peekPriority = "/"
        }
        let curIndex = "+-*/()%,".indexOf(curPriority)! - 40
        let peekIndex = "+-*/()%,".indexOf(peekPriority)! - 40
        const opPriority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
        return opPriority[peekIndex] >= opPriority[curIndex]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        */
        switch (current_op) {
            case "+" => return first_value + second_value
            case "-" => return first_value - second_value
            case "*" => return first_value * second_value
            case "/" => return first_value / second_value
            case "%" => return first_value % second_value
            else => throw IllegalArgumentException("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        */
        let expressionNoSpace = Regex("\\s+").replaceAll(expression, "")
        let expressionNoEquals = Regex("=$").replaceAll(expressionNoSpace, "")
        const expressionArr = expressionNoEquals.toCharArray()
        var transformed = ""
        for (i in 0 ... expressionArr.size - 1) {
            var c = String.fromChar(expressionArr[i])
            if (c == "-") {
                if (i == 0 || "+-*/(Ee".indexOf(String.fromChar(expressionArr[i - 1])) != -1) {
                    c = "~"
                }
            }
            transformed += c
        }
        if (transformed.first() == '~' && (transformed.size > 1 && transformed[1] == '(')) {
            transformed = "0" + transformed.replaceFirst("~", "-")
        }
        return transformed
    }
}

