                                employee.department = v
                            } else {
                                return false
                            }
                        case "salary" => 
                            if let v = value as? Int64 {
                                employee.salary = v
                            } else {
                                return false
                            }
                        default => return false
                    }
                }
                return true
            case None => return false
        }
    }

