            let octets = ip_address.split('.')
            for octet in octets {
                let num = octet.parseInt64()
                let binary = num.toBinaryString(8) // 8 bits for each octet
                binary_octets.add(binary)
            }
            return binary_octets.join('.')
        } else {
            return ""
        }
    }
