import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        var rows = BOARD_SIZE[0]
        var cols = BOARD_SIZE[1]
        var newBoard = ArrayList<ArrayList<String>>(rows)
        var random = Random()
        for (i in 0..rows) {
            var row = ArrayList<String>(cols)
            for (j in 0..cols) {
                var idx = random.nextInt64(ICONS.size())
                row.add(ICONS[idx])
            }
            newBoard.add(row)
        }
        return newBoard
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Check position range
        if x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1] || 
           x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1] {
            return false
        }

        // Check same position
        if pos1 == pos2 {
            return false
        }

        // Check same icon
        if board[x1 as Int64][y1 as Int64] != board[x2 as Int64][y2 as Int64] {
            return false
        }

        // Check path
        return has_path(pos1: pos1, pos2: pos2)
    }

