    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if !(data is Tuple || data is ArrayList) {
            throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        }

        if data is Tuple {
            let (sub_list, total_num) = data as! Tuple
            let arr = sub_list as! ArrayList<Int64>
            let n = arr.size()
            if total_num == 0 || n == 0 {
                return (0.0, ArrayList([0.0]))
            }

            var mr_np: ArrayList<Float64> = ArrayList()
            for i in range(0..<n) {
                let rank_i = 1.0 / (i + 1)
                mr_np.add(Float64(arr[i]) * rank_i)
            }

            var mr: Float64 = 0.0
            for team in mr_np {
                if team > 0 {
                    mr = team
                    break
                }
            }
            return (mr, ArrayList([mr]))
        } else {
            let data_list = data as! ArrayList
            var separate_result: ArrayList<Float64> = ArrayList()
            for item in data_list {
                let (sub_list, total_num) = item as! Tuple
                let arr = sub_list as! ArrayList<Int64>
                let n = arr.size()

                if total_num == 0 || n == 0 {
                    separate_result.add(0.0)
                    continue
