                var mr_np: ArrayList<Float64> = ArrayList()
                for i in range(0..<n) {
                    let rank_i = 1.0 / (i + 1)
                    mr_np.add(Float64(arr[i]) * rank_i)
                }

                var mr: Float64 = 0.0
                for team in mr_np {
                    if team > 0 {
                        mr = team
                        break
                    }
                }
                separate_result.add(mr)
            }

            var sum: Float64 = 0.0
            for result in separate_result {
