import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z\\s]", Unicode)
        for (string in string_list) {
            let processed_string = regex.replaceAll(string.lowercaseString(), "")
            let words = ArrayList<String>(processed_string.split(by: { c => !c.isWhitespace() }))
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var word_frequency = HashMap<String, Int64>()
        for (words in words_list) {
            for (word in words) {
                if (word_frequency.containsKey(word)) {
                    word_frequency[word] = word_frequency[word]! + 1
                } else {
                    word_frequency[word] = 1
                }
            }
        }
        var entries = ArrayList<MapEntry<String, Int64>>()
        for ((k, v) in word_frequency) {
            entries.add(MapEntry<String, Int64>(k, v))
        }
        sort(
            entries,
            by: { l: MapEntry<String, Int64>, r: MapEntry<String, Int64> => l.value.compare(r.value) },
            descending: true
        )
        var top_5_word_frequency = HashMap<String, Int64>()
        let count = minInt64(entries.size(), 5)
        for (i in 0..<count) {
            let entry = entries[i]!
            top_5_word_frequency[entry.key] = entry.value
        }
        return top_5_word_frequency
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        let word_frequency_dict = this.calculate_word_frequency(words_list)
        return word_frequency_dict
    }
}

