        // 创建事务对象
        let tx = cn.createTransaction()
        try {
            // 插入第一条数据
            psInsert.set<String>(0, "mkyong")
            psInsert.set<Array<Byte>>(1, Array<Byte>(1, repeat: 10))
            psInsert.set<DateTime>(2, DateTime.now())
