import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.141592653589793

    public init() {}

    public func cos(x: Float64): Float64 {
        /*
        Calculate the cos value of the x-degree angle
        :param x:Float64
        :return:Float64
        >>> tricalculator = TriCalculator()
        >>> tricalculator.cos(60.0)
        0.5
        */
        return self.round(self.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        /*
        Calculate the factorial of a
        :param a: Int64
        :return: Decimal
        >>> tricalculator.factorial(5)
        Decimal(120)
        */
        var b: Decimal = 1.0
        var n = a
        while n != 1 {
            b = b * n.toDecimal()
            n = n - 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        /*
        Finding the n-order Taylor expansion value of cos (x/180 * pi)
        :param x: Float64
        :param n: Int64
        :return: Float64
        >>> tricalculator.taylor(60.0, 50)
        0.5000000000000001
        */
        let x_rad = x / 180.0 * self.PI
        var a: Float64 = 1.0
        let count_max = n - 1
        var count: Int64 = 1
        for k in 1..count_max {
            let power = 2.0 * k.toFloat64()
            let numerator = x_rad ** power
            let denom = self.factorial(2 * k).toFloat64()
            let term = numerator / denom
            if count % 2 != 0 {
                a = a - term
            } else {
                a = a + term
            }
            count = count + 1
        }
        return a
    }

    public func sin(x: Float64): Float64 {
        /*
        Calculate the sin value of the x-degree angle
        :param x: Float64
        :return: Float64
        >>> tricalculator.sin(30.0)
        0.5
        */
        let x_rad = x / 180.0 * self.PI
        var g: Float64 = 0.0
        var t: Float64 = x_rad
        var n: Int64 = 1

        while abs(t) >= 1e-15 {
            g = g + t
            n = n + 1
            t = -t * x_rad * x_rad / (2.0 * n.toFloat64() - 1.0) / (2.0 * n.toFloat64() - 2.0)
        }
        return self.round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        /*
        Calculate the tan value of the x-degree angle
        If abs(this.cos(x) - 0.0) > 0.000001, return None
        :param x: Float64
        :return: Option<Float64>
        >>> tricalculator.tan(45.0)
        1.0
        */
        let cos_val = self.cos(x)
        if abs(cos_val) < 1e-6 {
            return None
        }
        let sin_val = self.sin(x)
        let result = sin_val / cos_val
        return Some(self.round(result, 10))
    }
}

