import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        func unit_vec(v: ArrayList<Float64>): ArrayList<Float64> {
            let norm = sqrt(v.foldLeft(0.0) { acc, x => acc + x * x })
            if norm <= 1e-10 {
                return v
            }
            return v.map { x => x / norm }
        }

        let u1 = unit_vec(vector_1)
        let u2 = unit_vec(vector_2)

        if u1.size() != u2.size() {
            throw IllegalArgumentException("Vectors must be of the same length")
        }

        var dot_product = 0.0
        for i in 0..<u1.size() {
            dot_product += u1[i] * u2[i]
        }

        return dot_product
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm_v1 = sqrt(vector_1.foldLeft(0.0) { acc, x => acc + x * x })
        if norm_v1 <= 1e-10 {
            return ArrayList<Float64>(vectors_all.map { _ => 0.0 })
        }

        let result = ArrayList<Float64>()
        for vec in vectors_all {
            let norm_vec = sqrt(vec.foldLeft(0.0) { acc, x => acc + x * x })
            if norm_vec <= 1e-10 {
                result.add(0.0)
                continue
            }

            var dot_product = 0.0
            for i in 0..<vector_1.size() {
                if i >= vec.size() {
                    throw IllegalArgumentException("All vectors must be of the same length")
                }
                dot_product += vector_1[i] * vec[i]
            }

            result.add(dot_product / (norm_v1 * norm_vec))
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.size() == 0 || vector_list_2.size() == 0 {
            throw IllegalArgumentException("At least one of the passed list is empty.")
        }

        func average_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
            if vectors.size() == 0 {
                return ArrayList<Float64>()
            }
            let dim = vectors[0].size()
            let result = ArrayList<Float64>(dim, { _ => 0.0 })

            for vec in vectors {
                if vec.size() != dim {
                    throw IllegalArgumentException("All vectors must be of the same length")
                }
                for i in 0..<dim {
                    result[i] += vec[i]
                }
            }

            for i in 0..<dim {
                result[i] /= vectors.size()
            }

            return result
        }

        let avg1 = average_vector(vector_list_1)
        let avg2 = average_vector(vector_list_2)

        return similarity(avg1, avg2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let index_2_key_map = HashMap<Int64, String>()
        let count_list = ArrayList<Float64>()

        var index: Int64 = 0
        for (key, count) in number_dict.pairs() {
            index_2_key_map[index] = key
            count_list.add(count)
            index += 1
        }

        let a = ArrayList<Float64>(count_list.map { count =>
            log((total_num + 1) / (count + 1))
        })

        let result = HashMap<String, Float64>()
        for (index, w) in a.enumerate() {
            let key = index_2_key_map[index]
            result[key] = w
        }

        return result
    }
}

